CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_self ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE id='0059b776-a1fd-4537-a2c8-b6f15134eee5';
CREATE TABLE public.app_access (user_id uuid PRIMARY KEY, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','blocked')), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.app_access TO authenticated;
GRANT ALL ON public.app_access TO service_role;
ALTER TABLE public.app_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_read_self ON public.app_access FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.app_access(user_id,status) SELECT id,'pending' FROM auth.users;
CREATE FUNCTION public.is_access_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'); $$;
REVOKE ALL ON FUNCTION public.is_access_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_access_admin() TO authenticated;
CREATE FUNCTION public.has_app_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.is_access_admin() OR EXISTS(SELECT 1 FROM public.app_access WHERE user_id=auth.uid() AND status='approved'); $$;
REVOKE ALL ON FUNCTION public.has_app_access() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_app_access() TO authenticated;
CREATE FUNCTION public.get_app_access() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('admin',public.is_access_admin(),'status',CASE WHEN public.is_access_admin() THEN 'approved' ELSE COALESCE((SELECT status FROM public.app_access WHERE user_id=auth.uid()),'pending') END); $$;
REVOKE ALL ON FUNCTION public.get_app_access() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_app_access() TO authenticated;
CREATE FUNCTION public.list_app_users() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.is_access_admin() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',u.id,'email',u.email,'created_at',u.created_at,'status',CASE WHEN EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u.id AND r.role='admin') THEN 'owner' ELSE COALESCE(a.status,'pending') END) ORDER BY u.created_at DESC),'[]'::jsonb) FROM auth.users u LEFT JOIN public.app_access a ON a.user_id=u.id); END; $$;
REVOKE ALL ON FUNCTION public.list_app_users() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.list_app_users() TO authenticated;
CREATE FUNCTION public.set_app_access(target_user_id uuid, new_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.is_access_admin() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF; IF new_status NOT IN ('approved','blocked') THEN RAISE EXCEPTION 'Situação inválida'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target_user_id AND role='admin') THEN RAISE EXCEPTION 'O acesso do proprietário não pode ser alterado'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=target_user_id) THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF; INSERT INTO public.app_access(user_id,status,updated_by) VALUES(target_user_id,new_status,auth.uid()) ON CONFLICT(user_id) DO UPDATE SET status=EXCLUDED.status,updated_at=now(),updated_by=auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.set_app_access(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_app_access(uuid,text) TO authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','clientes','apontamentos','valores_vigencia','agendamentos','relatorios_salvos','apontamento_pecas','lembretes','dados_empresa','pecas','orcamentos','orcamento_itens','recebimentos_avulsos'] LOOP EXECUTE format('CREATE POLICY require_approved_access ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.has_app_access()) WITH CHECK (public.has_app_access())', t); END LOOP; END $$;